local AiBotEvents = import('/lua/AiBot/AI/AiBotEvents.lua')

do --Per Balthazaar - encasing the code in do .... end means that you dont have to worry about using unique variables
    local AiBotOldProjectile = Projectile
    Projectile = Class(AiBotOldProjectile) {

        OnImpact = function(self, targetType, targetEntity)
            if targetType == 'Terrain' then ForkThread(AiBotEvents.OnImpactTerrain, self, targetType, targetEntity, self:GetPosition(), self:GetCurrentTargetPosition()) end
            AiBotOldProjectile.OnImpact(self, targetType, targetEntity)
        end,
        --[[OnTrackTargetGround = function(self)
            AiBotOldProjectile.OnTrackTargetGround(self)
            ForkThread(AiBotEvents.ProjectileFiredAtGround,self)
        end,--]]
        OnCreate = function(self, inWater)
            AiBotOldProjectile.OnCreate(self, inWater)
            ForkThread(AiBotEvents.ProjectileCreated,self, inWater)
        end,
        OnKilled = function(self, instigator, type, overkillRatio)
            --Destructive hook
            -- callbacks for launcher to have an idea what is going on for AIs
            local launcher = self.Launcher
            if not IsDestroyed(launcher) then
                launcher:OnMissileIntercepted(self:GetCurrentTargetPosition(), instigator, self:GetPosition(), self)

                -- keep track of the number of intercepted missiles
                --DiskGetFileInfo used as a proxy for checking if bFAFactive = true; for non-FAF increasing the kills could cause combat units with built in TMD like cruisers to vet early
                if not IsDestroyed(instigator) and instigator.GetStat and (DiskGetFileInfo('/lua/sim/navutils.lua') or (instigator.UnitId and EntityCategoryContains(categories.ANTIMISSILE * categories.STRUCTURE - categories.DIRECTFIRE, instigator.UnitId))) then
                    instigator:UpdateStat('KILLS', instigator:GetStat('KILLS', 0).Value + 1)
                end
            end

            self:CreateImpactEffects(self.Army, self.FxOnKilled, self.FxOnKilledScale)
            self:Destroy()
        end,
        OnTrackTargetGround = function(self)
            if self.OriginalTarget.IsRedirected then
                local target = self.OriginalTarget or self:GetTrackingTarget() or self.Launcher:GetTargetEntity()
                --LOG('target.Launcher.UnitId='..(target.Launcher.UnitId or 'nil')..'; EntityId='..(target.Launcher.EntityId or 'nil')..'; .Launcher.UnitId='..(self.Launcher.UnitId or 'nil')..'; EntityId='..(self.Launcher.EntityId or 'nil')..'; target reprs='..reprs(target)..'; will now do launcher reprs='..reprs(self.Launcher))
                if target.Launcher.EntityId == target.CreatedByWeapon.unit.EntityId then
                    --Only consider if 'launcher' was Cybran loyalist or cruiser (that can deflect), and target doesnt have antimissile
                    if self.Launcher then
                        if EntityCategoryContains(categories.ANTIMISSILE * categories.MOBILE * categories.CYBRAN, self.Launcher.UnitId) and EntityCategoryContains(categories.MOBILE, target.CreatedByWeapon.unit.UnitId) then
                            --Is this an AiBot unit?
                            ForkThread(AiBotEvents.MissileReflected,target.CreatedByWeapon.unit, self.Launcher)
                        end
                    end
                end
            end
            AiBotOldProjectile.OnTrackTargetGround(self)
        end,
    }
end